const express = require('express');
const fs = require('fs');
const path = require('path');
const { pipeline, Transform } = require('stream');
const { BiometricProfile } = require('../models/biometric');

const app = express();

class BiometricVectorFormatStream extends Transform {
  constructor() {
    super();
  }

  _transform(chunk, encoding, callback) {
    const header = Buffer.alloc(8);
    header.writeUInt32BE(512, 0);
    header.writeUInt32BE(chunk.length, 4);
    callback(null, Buffer.concat([header, chunk]));
  }
}

app.get('/biometrics/:vectorId/stream-template', async (req, res) => {
  if (!req.user || !req.user.id) {
    return res.status(401).send('Authentication required');
  }

  // Validate that the biometric template is assigned to the authenticated user or authorized officer
  const profile = await BiometricProfile.findOne({
    where: {
      vectorId: req.params.vectorId,
      userId: req.user.id
    }
  });

  if (!profile) {
    return res.status(403).send('Access denied to biometric vector template');
  }

  const vectorFile = path.join('/storage/biometrics/templates', `${req.params.vectorId}.vec`);
  if (!fs.existsSync(vectorFile)) {
    return res.status(404).send('Template not found');
  }

  res.setHeader('Content-Type', 'application/octet-stream');
  res.setHeader('Content-Disposition', 'attachment; filename="face_vector.bin"');

  const readStream = fs.createReadStream(vectorFile);
  const formatStream = new BiometricVectorFormatStream();

  pipeline(readStream, formatStream, res, (err) => {
    if (err && !res.headersSent) {
      res.status(500).send('Pipeline processing failed');
    }
  });
});

app.listen(9001);
